<template lang="html">
  <section class="tables">
    <div class="row">
      <div class="col-lg-12 grid-margin stretch-card">
        <div class="card">
          <div class="card-body">
            <h3 class="card-title mb-3">List of Users</h3>

            <div class="form-group mb-3">
              <input type="text" class="form-control" placeholder="Search Users" v-model="search" @keyup="get_users()">
            </div>

            <div class="table-responsive">
              <table class="table text-center">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Username</th>
                    <th>Display Name</th>
                    <th>Peddler No</th>
                    <th>Role</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-if="loader_spinner">
                    <td colspan="6" class="text-center">
                      <span class="spinner-border" role="status"></span>
                    </td>
                  </tr>
                  <tr v-else v-for="(row, i) in list_users" :key="i">
                    <td>{{ row.ID }}</td>
                    <td>{{ row.user_login }}</td>
                    <td>{{ row.display_name }}</td>
                    <td>{{ row.peddler_customer_no }}</td>
                    <td>{{ row.user_role == 1 ? 'Peddler' : row.user_role == 3 ? 'Admin' : 'Customer' }}</td>
                    <td>
                      <button class="btn btn-primary"
                        @click="openUserModal(row.ID, row.user_login, row.display_name, row.peddler_customer_no, row.user_role)">
                        <i class="mdi mdi-pencil" style="margin:0"></i>
                      </button>
                    </td>
                  </tr>
                </tbody>
                <tfoot>
                  <tr>
                    <td colspan="6" class="text-center">
                      <paginate :page-count="page_count" :container-class="'pagination text-center'"
                        page-class="page-item" prev-link-class="page-link" next-link-class="page-link"
                        page-link-class="page-link" prev-text="PREV" next-text="NEXT" :click-handler="get_users">
                      </paginate>
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Update User Modal -->
    <modal name="userModal" @before-open="beforeUserModalOpen" :min-height="320" :scrollable="true" height="auto">
      <div class="modal-body">
        <form>
          <div class="form-group mb-2">
            <label>Username</label>
            <input type="text" readonly class="form-control" v-model="user_login">
          </div>
          <div class="form-group mb-2">
            <label>Peddler No</label>
            <div class="d-flex">
              <input type="text" class="form-control" v-model="peddler_no">
              <button type="button" class="btn btn-info ml-2" @click="searchPeddlerNo">
                <i class="mdi mdi-magnify" style="font-size: 24px;"></i>
              </button>
            </div>

            <div v-if="showPeddlerDetails" class="d-flex gap-2">
              <input type="text" readonly class="form-control" placeholder="Peddler Name"
                v-model="peddler_customer_name">
              <input type="text" readonly class="form-control" placeholder="Peddler Percentage"
                v-model="peddler_percentage">
            </div>
          </div>
          <div class="form-group mb-2">
            <label>Role</label>
            <select class="form-control" v-model="user_role">
              <option disabled selected value="">-- USER ROLE --</option>
              <option value="3">Admin</option>
              <option value="1">Peddler</option>
            </select>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-default" @click="hideUserModal">Cancel</button>
        <button type="button" class="btn btn-success" @click="update_user">Update</button>
      </div>
    </modal>

  </section>
</template>

<script lang="js">
/* eslint-disable */
export default {
  name: 'users',
  data() {
    return {
      search: '',
      list_users: [],
      page_count: 0,
      user_id: 0,
      user_login: '',
      display_name: '',
      peddler_no: '',
      user_role: 0,
      loader_spinner: true,
      showPeddlerDetails: false,
      peddler_customer_name: 'sdsdsd',
      peddler_percentage: '5'
    }
  },
  methods: {
    searchPeddlerNo() {
      // Replace with your actual search logic
      this.showPeddlerDetails = !this.showPeddlerDetails
    },
    async update_user() {
      try {
        const query = {
          admin_user_id: localStorage.getItem('user_id'),
          user_id: this.user_id,
          peddler_customer_no: this.peddler_no,
          peddler_customer_name: this.peddler_customer_name,
          peddler_customer_percentage: this.peddler_percentage,
          user_login: this.user_login,
          display_name: this.display_name,
          user_role: this.user_role
        }
        const result = await this.$axios.post(this.$apiUrl + "update_user", query)
        if (result.data == true) {
          this.hideUserModal()
          await this.get_users()
          this.$swal('Account Updated!', 'You successfully updated an account')
        }
      } catch (e) {
        this.$swal('Error', e.message, 'error')
      }
    },
    async get_users(page = 1) {
      this.loader_spinner = true
      try {
        const query = {
          p_page: page,
          p_search: this.search,
          p_currentSort: 'user_id',
          p_currentSortDir: 'desc'
        }
        const result = await this.$axios.post(this.$apiUrl + "get_users", query)
        this.list_users = result.data.res
        this.page_count = parseInt(result.data.page_count)
      } catch (e) {
        this.$swal('Error', e.message, 'error')
      }
      this.loader_spinner = false
    },
    beforeUserModalOpen(event) {
      this.user_id = event.params.ID
      this.user_login = event.params.user_login
      this.display_name = event.params.display_name
      this.peddler_no = event.params.peddler_no
      this.user_role = event.params.user_role
    },
    openUserModal(ID, user_login, display_name, peddler_no, user_role) {
      this.$modal.show('userModal', { ID, user_login, display_name, peddler_no, user_role })
    },
    hideUserModal() {
      this.user_id = 0
      this.user_login = ''
      this.peddler_no = ''
      this.user_role = 0
      this.$modal.hide('userModal')
    },
  },
  mounted() {
    this.get_users()
  }
}
</script>

<style scoped lang="scss">
.pagination {
  display: flex;
  justify-content: center;
}

.gap-2 {
  margin-top: 0.5rem;
}

.gap-2>*:not(:last-child) {
  margin-right: 0.5rem;
}
</style>



