<template lang="html">
    <section class="tables">
        <div class="row">
            <div class="col-lg-12 grid-margin stretch-card">
                <div class="card">
                    <div class="card-body">
                        <div class="row">
                            <div class="col-sm-6">
                                <h3 class="card-title mb-3">List of Coupons</h3>
                            </div>
                            <div class="col-sm-6 text-right">
                                <button class="btn btn-success" type="button" @click="openAddNewCouponModal">Add New
                                    Coupon</button>
                            </div>
                        </div>
                        <div class="table-responsive">
                            <table class="table text-center">
                                <thead>
                                    <tr>
                                        <th>ID</th>
                                        <th>Coupon Name</th>
                                        <th>Coupon Status</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-if="loader_spinner">
                                        <td colspan="4" class="text-center">
                                            <span class="spinner-border" role="status"></span>
                                        </td>
                                    </tr>
                                    <tr v-else v-for="(row, i) in list_coupons" :key="i">
                                        <td>{{ row.ID }}</td>
                                        <td>{{ row.post_title }}</td>
                                        <td>{{ row.post_status == 'publish' ? 'Active' : 'Inactive' }}</td>
                                        <td><button class="btn btn-sm btn-info text-center"
                                                v-on:click="openUpdateCouponModal(row.ID)"><i class="mdi mdi-pencil"
                                                    style="margin:0"></i></button> | <button
                                                class="btn btn-sm btn-danger text-center"
                                                v-on:click="delete_coupon(row.ID, row.post_title)"><i
                                                    class="mdi mdi-delete" style="margin:0"></i></button>
                                        </td>
                                    </tr>
                                </tbody>
                                <tfoot>
                                    <tr>
                                        <td colspan="4" class="text-center">
                                            <paginate :page-count="total_coupons"
                                                :container-class="'pagination text-center'" page-class="page-item"
                                                prev-link-class="page-link" next-link-class="page-link"
                                                page-link-class="page-link" prev-text="PREV" next-text="NEXT"
                                                :click-handler="get_coupons">
                                            </paginate>
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <modal id="addNewCouponModal" name="addNewCouponModal" height="auto" :scrollable="true">
            <div class="modal-body">
                <div id="customTab">
                    <h5 class="mb-3">
                        {{ modalMode === 'create' ? 'Create Coupon' : 'Update Coupon' }}
                    </h5>

                    <div class="form-group mb-3">
                        <input type="text" class="form-control" placeholder="Coupon Code" v-model="coupon_name">
                    </div>

                    <b-card no-body>
                        <b-tabs card>
                            <b-tab title="General" active>
                                <div class="form-group mb-3">
                                    <label>Coupon Status</label>
                                    <select class="form-control" v-model="coupon_status">
                                        <option disabled selected value="">-- SELECT COUPON STATUS --</option>
                                        <option value="1">Active</option>
                                        <option value="0">Inactive</option>
                                    </select>
                                </div>
                                <div class="form-group mb-3">
                                    <label>Coupon Amount</label>
                                    <input type="number" class="form-control" v-model="coupon_amount">
                                </div>
                                <div class="form-group mb-3">
                                    <div class="checkbox-inline" style="padding-left: 20px;">
                                        <input type="checkbox" class=" form-check-input" v-model="free_shipping">
                                        <label class="form-check-label" style="padding-top:5px;">Free Shipping</label>
                                    </div>
                                </div>
                                <div class="form-group" style="position:relative;">
                                    <label for="dateFromPicker">Coupon Expiry Date:</label>
                                    <date-picker v-model="date_expiry" class="form-control" value-type="format"
                                        format="YYYY-MM-DD" append-to-body
                                        :popup-style="{ zIndex: 10000001 }"></date-picker>
                                </div>
                            </b-tab>
                            <b-tab title="Usage Restriction">
                                <div class="form-group mb-3">
                                    <label>Minimum Amount Spend</label>
                                    <input type="number" class="form-control" v-model="minimum_spend">
                                </div>
                                <div class="form-group mb-3">
                                    <label>Maximum Amount Spend</label>
                                    <input type="number" class="form-control" v-model="maximum_spend">
                                </div>
                                <div class="form-group mb-3">
                                    <label>Excluded Categories</label>
                                    <select class="form-control" multiple="" v-model="excluded_categories"
                                        style="height:350px;">
                                        <option v-for="(row, i) in list_categories" :key="i" :value="row.term_id">{{
                                            row.category_name.replace(/&amp;/gi, "&").toUpperCase() }}</option>
                                    </select>
                                    {{ excluded_categories }}
                                </div>
                            </b-tab>
                            <b-tab title="Usage Limit">
                                <div class="form-group mb-3">
                                    <label>Usage Limit per Coupon</label>
                                    <input type="number" class="form-control" v-model="usage_per_coupon">
                                </div>
                                <div class="form-group mb-3">
                                    <label>Usage Limit per User</label>
                                    <input type="number" class="form-control" v-model="usage_per_user">
                                </div>
                            </b-tab>
                            <b-tab title="Miscellaneous">
                                <div class="checkbox-inline" style="padding-left: 20px;">
                                    <input type="checkbox" class=" form-check-input" v-model="auto_coupon">
                                    <label class="form-check-label" style="padding-top:5px;">Auto Coupon</label>
                                </div>
                            </b-tab>
                        </b-tabs>
                    </b-card>
                </div>
            </div>
            <div class="modal-footer">
                <button type="button" class="btn btn-default" @click="hideAddNewCouponModal">Close</button>
                <button type="button" class="btn btn-success" @click="handleSubmit">
                    {{ modalMode === 'create' ? 'Create Coupon' : 'Update Coupon' }}
                </button>
            </div>
        </modal>
    </section>
</template>

<script lang="js">
/* eslint-disable */
export default {
    name: 'users',
    data() {
        return {
            modalMode: 'create',
            selectedCouponId: null,
            coupon_name: '',
            coupon_status: '',
            coupon_amount: 0,
            free_shipping: false,
            date_expiry: null,
            minimum_spend: 0,
            maximum_spend: 0,
            excluded_categories: [],
            usage_per_coupon: 0,
            usage_per_user: 0,
            auto_coupon: false,
            search: '',
            currentSort: 'ID',
            currentSortDir: 'desc',
            list_coupons: [],
            total_coupons: 0,
            loader_spinner: true,
            list_categories: []
        }
    },
    methods: {
        async openAddNewCouponModal() {
            this.resetForm()
            this.modalMode = "create"
            this.selectedCouponId = null
            await this.get_categories()
            this.$modal.show('addNewCouponModal')
        },
        async openUpdateCouponModal(couponId) {
            try {
                this.resetForm()
                this.modalMode = "edit"
                this.selectedCouponId = couponId

                await this.get_categories()

                const res = await this.$axios.get(
                    this.$apiUrl + "get-coupon-details",
                    { params: { coupon_id: this.selectedCouponId } }
                )

                const data = res.data.data

                this.coupon_name = data.coupon_name
                this.coupon_status = data.coupon_status == 'publish' ? 1 : 0
                this.coupon_amount = data.coupon_amount
                this.free_shipping = data.free_shipping == 'yes' ? true : false
                this.date_expiry = data.date_expires
                this.minimum_spend = data.minimum_amount
                this.maximum_spend = data.maximum_amount
                this.excluded_categories = data.exclude_product_categories || []
                this.usage_per_coupon = data.usage_limit
                this.usage_per_user = data.usage_limit_per_user

                this.$modal.show("addNewCouponModal")

            } catch (e) {
                this.$swal("Error", e.message, "error")
            }
        },
        hideAddNewCouponModal() {
            this.$modal.hide('addNewCouponModal')
        },
        async handleSubmit() {
            if (this.modalMode === "create") {
                await this.create_coupon()
            } else {
                await this.update_coupon()
            }
        },
        async get_categories() {
            const result = await this.$axios.get(this.$apiUrl + "get-categories")
            this.list_categories = result.data
        },
        async delete_coupon(id, coupon_name) {
            const confirm = await this.$swal({
                title: "Delete Coupon?",
                text: "This action cannot be undone",
                icon: "warning",
                showCancelButton: true
            })


            if (!confirm.value) return

            await this.$axios.post(this.$apiUrl + "delete-coupon", {
                coupon_id: id,
                coupon_name: coupon_name,
                display_name: localStorage.getItem('display_name'),
                user_id: localStorage.getItem('user_id')
            })

            this.get_coupons()
            this.$swal("Deleted!", "Coupon successfully deleted", "success")
        },
        async update_coupon() {
            try {
                const query = {
                    coupon_id: this.selectedCouponId,
                    coupon_name: this.coupon_name,
                    couponAmount: this.coupon_amount,
                    couponFreeShipping: this.free_shipping,
                    couponExpiry: this.date_expiry,
                    couponMinimumSpend: this.minimum_spend,
                    couponMaximumSpend: this.maximum_spend,
                    couponExcludedCategories: this.excluded_categories,
                    couponUsageLimitCoupon: this.usage_per_coupon,
                    couponUsageLimitUser: this.usage_per_user,
                    couponStatus: this.coupon_status,
                    display_name: localStorage.getItem('display_name'),
                    user_id: localStorage.getItem('user_id')
                }

                const result = await this.$axios.post(
                    this.$apiUrl + "update-coupon",
                    query
                )

                if (result.data.msg === "success") {
                    this.get_coupons()
                    this.hideAddNewCouponModal()
                    this.$swal("Coupon Updated!", "Coupon successfully updated")
                }

            } catch (e) {
                this.$swal("Error", e.message, "error")
            }
        },
        async create_coupon() {
            try {
                const query = {
                    coupon_name: this.coupon_name,
                    couponAmount: this.coupon_amount,
                    couponFreeShipping: this.free_shipping,
                    couponExpiry: this.date_expiry,
                    couponMinimumSpend: this.minimum_spend,
                    couponMaximumSpend: this.maximum_spend,
                    couponExcludedCategories: this.excluded_categories,
                    couponUsageLimitCoupon: this.usage_per_coupon,
                    couponUsageLimitUser: this.usage_per_user,
                    couponStatus: this.coupon_status,
                    display_name: localStorage.getItem('display_name'),
                    user_id: localStorage.getItem('user_id')
                }

                const result = await this.$axios.post(this.$apiUrl + "create-coupon", query)

                if (result.data.msg == "success") {
                    this.resetForm()
                    this.get_coupons()
                    this.hideAddNewCouponModal()
                    this.$swal('Coupon Created!', 'You successfully created a coupon')
                }
            } catch (e) {
                this.$swal('Error', e.message, 'error')
            }
        },
        async get_coupons(page = 1) {
            this.loader_spinner = true
            try {
                let query = {
                    p_page: page,
                    p_search: this.search,
                    p_currentSort: this.currentSort,
                    p_currentSortDir: this.currentSortDir
                }
                const result = await this.$axios.get(this.$apiUrl + "get-coupons", query)
                this.list_coupons = result.data.data.data
                this.total_coupons = result.data.page_count
            } catch (e) {
                this.$swal('Error', e.message, 'error')
            }
            this.loader_spinner = false
        },
        async resetForm() {
            this.coupon_name = ''
            this.coupon_status = ''
            this.coupon_amount = 0
            this.free_shipping = false
            this.date_expiry = null
            this.minimum_spend = 0
            this.maximum_spend = 0
            this.excluded_categories = []
            this.usage_per_coupon = 0
            this.usage_per_user = 0
            this.auto_coupon = false
        },
    },
    async mounted() {
        await this.get_coupons()
    }
}
</script>

<style>
.pagination {
    display: flex;
    justify-content: center;
}

.gap-2 {
    margin-top: 0.5rem;
}

.gap-2>*:not(:last-child) {
    margin-right: 0.5rem;
}

.transaction-table {
    width: 100%;
}

.table-fixed {
    table-layout: fixed;
    width: 100%;
}

.table-header-wrapper {
    background: #fff;
    border-bottom: 1px solid #ddd;
}

.table-body-wrapper {
    height: 70vh;
    overflow-y: auto;
}

/* Prevent column mismatch */
.table-fixed th,
.table-fixed td {
    white-space: nowrap;
}

#addNewCouponModal {
    z-index: 10000000 !important;
}

/* Allow the datepicker to overflow the modal container */
.vm--modal {
    overflow: visible !important;
}

/* Ensure the datepicker stays on top of the modal overlay */
.b-form-datepicker .dropdown-menu {
    z-index: 10000001 !important;
}

/* This targets the calendar popup when append-to-body is used */
.b-form-datepicker-calendar__outer,
.dropdown-menu.show {
    z-index: 10000001 !important;
}

.swal2-container {
    z-index: 10000002 !important;
}

/* Force card-body spacing for tab panes */
#customTab .card .tab-content>.tab-pane {
    padding: 1rem;
}

/* Prevent double padding when card-body DOES exist */
#customTab .card .tab-content>.card-body {
    padding: 10px;
    margin: 10px;
}

#customTab .card-header {
    padding: 8px 16px;
}
</style>



