<template lang="html">
    <section class="orders">
        <div class="col-lg-12 grid-margin stretch-card">
            <div class="card">
                <div class="card-body" style="padding-left: 15px; padding-right: 15px;">
                    <h3 class="card-title">List of Pending Orders</h3>
                    <div class="table-responsive">
                        <!-- <div class="form-group">
                    <input type="text" class="form-control" placeholder="Search Products" v-model="search" v-on:keyup="get_orders()">
                </div> -->
                        <table class="table text-center">
                            <thead>
                                <tr>
                                    <th>Order No</th>
                                    <th>Customer Name</th>
                                    <th>Mode of Payment</th>
                                    <th>Date Ordered</th>
                                    <th>Total Amount</th>
                                    <th>Status</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr v-show="loader_spinner">
                                    <th colspan="7" class="text-center">
                                        <span class="spinner-border" role="status"></span>
                                    </th>
                                </tr>
                                <tr v-show="!loader_spinner" v-for="(row, i) in list_orders" :key="i">
                                    <td>{{ row.order_id }}</td>
                                    <td>{{ row.first_name + ' ' + row.last_name }}</td>
                                    <td>{{ row.payment_method_title }}</td>
                                    <td>{{ row.date_created_gmt | laymandate }}</td>
                                    <td>{{ row.total_amount }}</td>
                                    <td>{{ row.status | wpstatus }}</td>
                                    <td>
                                        <button class="btn btn-primary" @click="openOrderModal(row)"><i
                                                class="mdi mdi-eye" style="margin:0"></i></button>
                                    </td>
                                </tr>
                            </tbody>
                            <tfoot>
                                <tr>
                                    <td class="page text-center" colspan="7" align="center">
                                        <paginate :pageCount="page_count" :container-class="'pagination text-center'"
                                            page-class="page-item" prev-link-class="page-link"
                                            next-link-class="page-link" page-link-class="page-link" prev-text="PREV"
                                            next-text="NEXT" :click-handler="get_orders"></paginate>
                                    </td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>
            </div>
        </div>
        <modal id="orderModal" name="orderModal" @before-open="beforeOrderModalOpen" height="auto" :width="900"
            :scrollable="true">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Order #{{ orderDetails.order_id }}</h5>
                </div>
                <div class="modal-body">
                    <div class="row center-block">
                        <div class="col-md-12">
                            <div class="row">
                                <div class="col-md-4">
                                    <p class="h6">
                                        <strong>Order Status</strong>
                                    </p>
                                    <div class="form-inline">
                                        <div class="form-group">
                                            <label for="orderStatus" style="padding-right: 10px;">Status</label>
                                            <select id="orderStatus" v-model="orderDetails.status" class="form-control"
                                                style="width: 150px;">
                                                <option value="wc-processing">Processing</option>
                                                <option value="wc-completed">Completed</option>
                                                <option value="wc-cancelled">Cancelled</option>
                                            </select>
                                        </div>
                                    </div>
                                </div>
                                <div class="col-md-6">
                                    <p class="h6">
                                        <strong>Customer Details</strong>
                                    </p>
                                    <div class="form-group">
                                        <p style="margin-bottom:8px;"><strong>Customer Name:</strong> {{
                                            orderDetails.first_name + ' ' + orderDetails.last_name }}</p>
                                        <p style="margin-bottom:8px;"><strong>Customer Address:</strong> {{
                                            orderDetails.address_1 + ' ' + ((orderDetails.address_2 == null) ? '' :
                                                orderDetails.address_2) + ' ' + orderDetails.city }}</p>
                                        <p style="margin-bottom:8px;"><strong>Customer Contact#:</strong> {{
                                            orderDetails.phone }}</p>
                                    </div>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-sm-12 col-md-12 col-lg-12">
                                    <strong>List of Items</strong>
                                    <div class="mb-2 text-right">
                                        <button class="btn btn-primary btn-sm" @click="addItem">
                                            Add Item
                                        </button>
                                    </div>
                                    <div class="table-responsive">
                                        <table class="table text-center">
                                            <thead>
                                                <tr>
                                                    <th>Item</th>
                                                    <th>Price</th>
                                                    <th>Quantity</th>
                                                    <th>Total</th>
                                                    <th>Action</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr v-show="loader_spinner_items">
                                                    <th colspan="5" class="text-center">
                                                        <span class="spinner-border" role="status"></span>
                                                    </th>
                                                </tr>
                                                <tr v-show="!loader_spinner_items" v-for="(row, i) in orderItems"
                                                    :key="row.row_id">
                                                    <td>
                                                        <input v-if="row.editing" v-model="row.order_item_name"
                                                            class="form-control form-control-sm"
                                                            @input="debouncedSearch(row, i)"
                                                            @keydown.down.prevent="navigateResults(i, 'down')"
                                                            @keydown.up.prevent="navigateResults(i, 'up')"
                                                            @keydown.enter.prevent="selectHighlighted(i)">
                                                        <span v-else>{{ row.order_item_name }}</span>

                                                        <div v-if="row.searchResults && row.searchResults.length"
                                                            class="search-dropdown">
                                                            <div v-for="(product, rIndex) in row.searchResults"
                                                                :key="product.id" class="search-item"
                                                                :class="{ active: row.highlightIndex === rIndex }"
                                                                @click="selectItem(product, i)">
                                                                {{ product.ProductID }} — {{ product.productName }}
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td>
                                                        {{ row.original_price }}
                                                    </td>
                                                    <td>
                                                        <input v-if="row.editing" type="number" v-model.number="row.Qty"
                                                            class="form-control form-control-sm" @input="updateItem(i)">
                                                        <span v-else>{{ row.Qty }}</span>
                                                    </td>
                                                    <td>
                                                        {{ row.subtotal || 0 }}
                                                    </td>
                                                    <td>
                                                        <button v-if="!row.editing" class="btn btn-sm btn-warning"
                                                            @click="editRow(row, i)">
                                                            Edit
                                                        </button>
                                                        <button v-if="row.editing" class="btn btn-sm btn-success"
                                                            @click="saveRow(row, i)">
                                                            Save
                                                        </button>
                                                    </td>
                                                </tr>
                                            </tbody>
                                            <tfoot>
                                                <tr>
                                                    <td class="text-right" colspan="4">
                                                        <strong>Order Total:</strong>
                                                    </td>
                                                    <td colspan="1">
                                                        {{ orderTotalPrice }}
                                                    </td>
                                                </tr>
                                            </tfoot>
                                        </table>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-danger" @click="hideOrderModal"
                        :disabled="isUpdating || isSending">Cancel</button>
                    <button type="button" class="btn btn-success"
                        @click="updateOrderDetails(orderDetails.order_id, orderDetails.status)"
                        :disabled="isUpdating || isSending">
                        <span v-if="isUpdating" class="spinner-border spinner-border-sm"></span>
                        <span v-if="!isUpdating">Update</span>
                        <span v-else> Updating...</span>
                    </button>
                    <button type="button" class="btn btn-info" @click="sendToPOS(orderDetails.order_id)"
                        :disabled="isUpdating || isSending">
                        <span v-if="isSending" class="spinner-border spinner-border-sm"></span>
                        <span v-if="!isSending">Send to POS</span>
                        <span v-else> Sending...</span>
                    </button>
                </div>
            </div>
        </modal>
    </section>
</template>
<script lang="js">
/* eslint-disable */
export default {
    name: 'pending_orders',
    data() {
        return {
            // search: '',
            list_orders: [],
            page_count: 0,
            prev: 'PREV',
            next: 'NEXT',
            currentSort: 'id',
            currentSortDir: 'desc',
            pagination: 'pagination',
            orderDetails: [],
            orderItems: [],
            orderTotalPrice: 0,
            loader_spinner: true,
            loader_spinner_items: true,
            searchTimeout: null,
            isUpdating: false,
            isSending: false,
        }
    },
    methods: {
        async sendToPOS(order_id) {
            this.isSending = true
            try {
                let query = {
                    order_id: order_id,
                    user_id: localStorage.getItem('user_id'),
                    display_name: localStorage.getItem('display_name'),
                }

                let result = await this.$axios.post(this.$apiUrl + "send_to_pos", query)
                await this.get_orders()
                this.$swal('Send to POS', result.data.msg)
                this.$modal.hide('orderModal')
            } catch (error) {
                this.$swal.fire({
                    title: 'Error',
                    text: error.message,
                    icon: 'error',
                    target: document.getElementById('orderModal'),
                    didOpen: () => {
                        setTimeout(() => {
                            document
                                .querySelectorAll('.swal2-container, .swal2-backdrop')
                                .forEach(el =>
                                    el.style.setProperty('z-index', '10000002', 'important')
                                );
                        }, 0);
                    }
                });
            } finally {
                this.isSending = false
            }
        },
        navigateResults(index, direction) {
            let row = this.orderItems[index];
            if (!row.searchResults) return;

            if (direction === "down") {
                row.highlightIndex =
                    (row.highlightIndex + 1) % row.searchResults.length;
            }

            if (direction === "up") {
                row.highlightIndex =
                    (row.highlightIndex - 1 + row.searchResults.length) %
                    row.searchResults.length;
            }
        },

        selectHighlighted(index) {
            let row = this.orderItems[index];
            if (!row.searchResults.length) return;

            let product = row.searchResults[row.highlightIndex];
            this.selectItem(product, index);
        },

        async selectItem(product, index) {
            let item = this.orderItems[index];

            item.productID = product.ProductID;
            item.order_item_name = product.productName;
            item.Qty = 1;

            const res = await this.$axios.get(
                this.$apiUrl + "select-product",
                {
                    params: {
                        ProductID: product.ProductID
                    }
                }
            );

            item.original_price = res.data;
            item.lineTotal = res.data;
            item.subtotal = res.data;

            item.searchResults = [];
            item.highlightIndex = 0;

            this.$set(this.orderItems, index, item);
        },
        debouncedSearch(row, index) {
            clearTimeout(this.searchTimeout);

            this.searchTimeout = setTimeout(() => {
                this.searchItems(row, index);
            }, 300);
        },

        async searchItems(row, index) {
            if (!row.order_item_name || row.order_item_name.length < 2) {
                row.searchResults = [];
                return;
            }

            try {
                const res = await this.$axios.get(
                    this.$apiUrl + "search-products",
                    {
                        params: {
                            search: row.order_item_name
                        }
                    }
                );

                let results = res.data;

                this.$set(this.orderItems[index], "searchResults", results);
                this.$set(this.orderItems[index], "highlightIndex", 0);

            } catch (err) {
                console.error(err);
            }
        },
        async updateItem(index) {
            let item = this.orderItems[index];

            if (!item.Qty || item.Qty <= 0) {
                item.Qty = 0;
                item.subtotal = 0;

                this.$set(this.orderItems, index, item);
                return;
            }

            item.subtotal = item.original_price * item.Qty;

            this.$set(this.orderItems, index, item);
        },
        async editRow(row, index) {
            const updatedRow = { ...row, editing: true };
            this.$set(this.orderItems, index, updatedRow);
        },
        async saveRow(row, index) {
            const qty = Number(row.Qty) || 0;
            const price = Number(row.original_price) || 0;
            const subtotal = price * qty;

            this.$set(this.orderItems[index], 'Qty', qty);
            this.$set(this.orderItems[index], 'subtotal', subtotal);
            this.$set(this.orderItems[index], 'editing', false);

            try {
                await this.$axios.post(this.$apiUrl + "audit-logs", {
                    order_id: row.order_id,
                    product_id: row.productID,
                    qty: qty,
                    admin_id: localStorage.getItem('user_id'),
                    admin_name: localStorage.getItem('display_name'),
                    desc: "UPDATE"
                });
            } catch (e) {
                console.error(e);
            }
        },

        async addItem() {
            this.orderItems.push({
                row_id: Date.now() + Math.random(), // ✅ ADD THIS
                order_id: this.orderDetails.order_id,
                order_item_name: "",
                productID: null, // ✅ also add this (important)
                price: 0,
                Qty: 1,
                lineTotal: 0,
                subtotal: 0,
                editing: true
            });
        },
        async updateOrderDetails(order_id, status) {
            await this.update_order(order_id, status)
        },
        async beforeOrderModalOpen(event) {
            this.orderDetails = event.params.order_details
        },
        async openOrderModal(row) {
            this.$modal.show('orderModal', { order_details: row })
            await this.get_order_items(row.order_id)
        },
        async hideOrderModal() {
            this.orderDetails = []
            this.orderItems = []
            this.orderTotalPrice = 0
            this.$modal.hide('orderModal')
        },
        async pageChanged(page) {
            await this.get_orders(page)
        },
        async get_orders(page = 1) {
            this.loader_spinner = true
            try {
                let query = {
                    // p_search: this.search,
                    p_page: page,
                    p_currentSort: this.currentSort,
                    p_currentSortDir: this.currentSortDir,
                    p_orderType: 'wc-processing'
                }

                let result = await this.$axios.post(this.$apiUrl + "get_orders", query)
                let res = result.data
                this.list_orders = res.res
                this.page_count = parseInt(res.page_count)
            } catch (e) {
                this.$swal('Error', e.message, 'error')
            }
            this.loader_spinner = false
        },
        async get_order_items(order_id) {
            this.loader_spinner_items = true
            try {
                let query = {
                    order_id: order_id
                }

                let result = await this.$axios.post(this.$apiUrl + "get_order_items", query)
                let res = result.data
                // ✅ ADD row_id to each item
                this.orderItems = res.map(item => ({
                    ...item,
                    row_id: Date.now() + Math.random()
                }));
            } catch (error) {
                this.$swal.fire({
                    title: 'Error',
                    text: error.message,
                    icon: 'error',
                    target: document.getElementById('orderModal'),
                    didOpen: () => {
                        setTimeout(() => {
                            document
                                .querySelectorAll('.swal2-container, .swal2-backdrop')
                                .forEach(el =>
                                    el.style.setProperty('z-index', '10000002', 'important')
                                );
                        }, 0);
                    }
                });
            }
            this.loader_spinner_items = false
        },
        async update_order(order_id, status) {
            try {
                this.isUpdating = true

                let query = {
                    order_id: order_id,
                    status: status,
                    display_name: localStorage.getItem('display_name'),
                    user_id: localStorage.getItem('user_id'),
                    // ✅ CLEAN PAYLOAD
                    items: this.orderItems.map(item => ({
                        productID: item.productID,
                        variationID: item.variationID || 0,
                        Qty: Number(item.Qty),
                        price: Number(item.original_price),           // ✅ UNIT PRICE
                        subtotal: Number(item.subtotal)      // ✅ TOTAL
                    }))
                }

                let res = await this.$axios.post(this.$apiUrl + "update_order", query)
                if (res.data.status) {
                    await this.get_orders()
                    this.$swal('Order Updated!', 'You successfully updated an order')
                    this.$modal.hide('orderModal')
                }
            } catch (error) {
                this.$swal.fire({
                    title: 'Error',
                    text: error.message,
                    icon: 'error',
                    target: document.getElementById('orderModal'),
                    didOpen: () => {
                        setTimeout(() => {
                            document
                                .querySelectorAll('.swal2-container, .swal2-backdrop')
                                .forEach(el =>
                                    el.style.setProperty('z-index', '10000002', 'important')
                                );
                        }, 0);
                    }
                });
            } finally {
                this.isUpdating = false
            }
        }
    },
    async mounted() {
        await this.get_orders()
    },
    watch: {
        orderItems: {
            handler: function () {
                this.orderTotalPrice = 0
                this.orderItems.forEach(p => {
                    this.orderTotalPrice = parseFloat(this.orderTotalPrice) + parseFloat(p.subtotal)
                })
            }, deep: true
        }
    },
}
</script>

<style scoped lang="scss">
.pagination {
    display: flex;
    justify-content: center;
}

#orderModal {
    z-index: 10000000 !important;
}

.swal2-container {
    z-index: 10000001 !important;
}

.search-dropdown {
    position: absolute;
    background: white;
    border: 1px solid #ddd;
    width: 100%;
    z-index: 999;
    max-height: 220px;
    overflow-y: auto;
}

.search-item {
    padding: 8px;
    cursor: pointer;
}

.search-item:hover,
.search-item.active {
    background: #eef3ff;
}
</style>


