<template lang="html">
    <section class="tables">
        <div class="row">
            <div class="col-lg-12 grid-margin stretch-card">
                <div class="card">
                    <div class="card-body">
                        <div class="row">
                            <div class="col-sm-6">
                                <h3 class="card-title mb-3">List of Peddler Customers</h3>
                            </div>
                            <div class="col-sm-6 text-right">
                                <button class="btn btn-success" type="button" @click="openExportExcelModal">Export
                                    Excel</button>
                            </div>
                        </div>
                        <div class="form-group mb-3">
                            <input type="text" class="form-control" placeholder="Search Users" v-model="search"
                                @keyup="get_users()">
                        </div>

                        <div class="table-responsive">
                            <table class="table text-center">
                                <thead>
                                    <tr>
                                        <th>Peddler No</th>
                                        <th>Customer Name</th>
                                        <th>Transaction No</th>
                                        <th>Amount</th>
                                        <th>Description</th>
                                        <th>Date</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-if="loader_spinner">
                                        <td colspan="7" class="text-center">
                                            <span class="spinner-border" role="status"></span>
                                        </td>
                                    </tr>
                                    <tr v-else v-for="(row, i) in list_users" :key="i">
                                        <td>{{ row.AccountNo }}</td>
                                        <td>{{ row.customername }}</td>
                                        <td>{{ row.TransactionNo }}</td>
                                        <td>{{ row.Amount }}</td>
                                        <td>{{ row.Description }}</td>
                                        <td>{{ row.LogDate | laymandate }}</td>
                                        <td><button class="btn btn-sm btn-info text-center"
                                                v-on:click="get_transaction(row.TransactionNo, row.TerminalNo, row.AccountNo)"><i
                                                    class="mdi mdi-eye" style="margin:0"></i></button>
                                        </td>
                                    </tr>
                                </tbody>
                                <tfoot>
                                    <tr>
                                        <td colspan="7" class="text-center">
                                            <paginate :page-count="page_count"
                                                :container-class="'pagination text-center'" page-class="page-item"
                                                prev-link-class="page-link" next-link-class="page-link"
                                                page-link-class="page-link" prev-text="PREV" next-text="NEXT"
                                                :click-handler="get_users">
                                            </paginate>
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Transaction View Modal -->
        <modal id="transactionModal" name="transactionModal" width="95vw" height="85vh" :styles="{ minHeight: '60vh' }"
            :scrollable="true">
            <div class="modal-body">
                <div class="transaction-table">

                    <!-- FIXED HEADER -->
                    <div class="table-header-wrapper">
                        <table class="table text-center table-fixed">
                            <thead>
                                <tr>
                                    <th>Product ID</th>
                                    <th>Barcode</th>
                                    <th>Description</th>
                                    <th>UOM</th>
                                    <th>Quantity</th>
                                    <th>Price</th>
                                    <th>Total</th>
                                </tr>
                            </thead>
                        </table>
                    </div>

                    <!-- SCROLL BODY -->
                    <div class="table-body-wrapper">
                        <table class="table text-center table-fixed">
                            <tbody>
                                <tr v-if="loader_transaction">
                                    <td colspan="6">
                                        <span class="spinner-border"></span>
                                    </td>
                                </tr>

                                <tr v-for="(row, i) in list_transaction" :key="i">
                                    <td>{{ row.ProductID }}</td>
                                    <td>{{ row.Barcode }}</td>
                                    <td>{{ row.Description }}</td>
                                    <td>{{ row.UOM }}</td>
                                    <td>{{ row.Qty }}</td>
                                    <td>{{ row.Price.toFixed(2) }}</td>
                                    <td>{{ (row.Qty * row.Price).toFixed(2) }}</td>
                                </tr>
                            </tbody>

                            <tfoot>
                                <tr>
                                    <td colspan="6" class="text-right"><strong>TOTAL</strong></td>
                                    <td><strong>{{ total_transaction.toFixed(2) }}</strong></td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>

                </div>
            </div>
            <div class="modal-footer">
                <button type="button" class="btn btn-default" @click="hideTransactionModal">Close</button>
            </div>
        </modal>

        <modal id="transactionModal" name="exportExcelModal" :adaptive="true" height="auto" :scrollable="true"
            boundary="viewport">
            <div class=" modal-body">
                <div class="row center-block">
                    <div class="col-md-6 text-center">
                        <div class="form-group" style="position:relative;">
                            <label for="dateFromPicker">Chooste Date From:</label>
                            <date-picker v-model="dateFrom" value-type="format" format="YYYY-MM-DD" append-to-body
                                :popup-style="{ zIndex: 10000001 }"></date-picker>
                        </div>
                    </div>
                    <div class="col-md-6 text-center">
                        <div class="form-group" style="position:relative;">
                            <label for="dateFromPicker">Choose Date To:</label>
                            <date-picker v-model="dateTo" value-type="format" format="YYYY-MM-DD" append-to-body
                                :popup-style="{ zIndex: 10000001 }"></date-picker>
                        </div>
                    </div>
                    <div class="col-md-12 text-center">
                        <button type="button" class="btn btn-lg btn-block btn-success" @click="exportExcelFunc"
                            :disabled="isExporting">
                            <span v-if="isExporting" class="spinner-border spinner-border-sm" role="status"
                                aria-hidden="true"></span>
                            <span v-if="!isExporting">Export Excel</span>
                            <span v-else>Processing...</span></button>
                    </div>
                </div>
            </div>
            <div class="modal-footer">
                <button type="button" class="btn btn-default" @click="hideExportExcelModal">Close</button>
            </div>
        </modal>

    </section>
</template>

<script lang="js">
/* eslint-disable */
export default {
    name: 'users',
    data() {
        return {
            search: '',
            list_users: [],
            list_transaction: [],
            total_transaction: 0,
            page_count: 0,
            loader_spinner: true,
            loader_transaction: true,
            dateTo: '',
            dateFrom: '',
            isExporting: false
        }
    },
    methods: {
        openExportExcelModal() {
            this.$modal.show('exportExcelModal')
        },
        hideExportExcelModal() {
            this.$modal.hide('exportExcelModal')
        },
        async exportExcelFunc() {
            this.isExporting = true;

            try {
                const query = {
                    date_from: this.dateFrom,
                    date_to: this.dateTo,
                }
                // Make request to backend
                const response = await this.$axios.get(this.$apiUrl + 'export-excel', {
                    params: query,
                    responseType: 'blob', // important
                });

                // Create Blob from response
                const blob = new Blob([response.data], {
                    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                });

                // Create temporary link element
                const url = window.URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = url;
                link.setAttribute(
                    'download',
                    `Peddler_Customers_${query.date_from}_to_${query.date_to}.xlsx`
                );

                // Append to body, trigger click, then remove
                document.body.appendChild(link);
                link.click();
                link.remove();

                // Optional: revoke object URL to free memory
                window.URL.revokeObjectURL(url);
                // this.hideExportExcelModal();
            } catch (error) {
                this.$swal.fire({
                    title: 'Error',
                    text: error.message,
                    icon: 'error',
                    target: document.getElementById('transactionModal'),
                    didOpen: () => {
                        setTimeout(() => {
                            document
                                .querySelectorAll('.swal2-container, .swal2-backdrop')
                                .forEach(el =>
                                    el.style.setProperty('z-index', '10000002', 'important')
                                );
                        }, 0);
                    }
                });
            } finally {
                this.isExporting = false;
            }
        },
        openTransactionModal() {
            this.$modal.show('transactionModal')
        },
        hideTransactionModal() {
            this.dateFrom = ''
            this.dateTo = ''
            this.$modal.hide('transactionModal')
        },
        async get_transaction(transactionNo, terminalNo, accountNo) {
            this.loader_transaction = true
            try {
                const query = {
                    transactionNo: transactionNo,
                    terminalNo: terminalNo,
                    accountNo: accountNo
                }
                const result = await this.$axios.post(this.$apiUrl + "getDownlineCustomerTransaction", query)
                this.list_transaction = result.data.result
                this.total_transaction = result.data.total
                this.openTransactionModal()
            } catch (e) {
                this.$swal('Error', e.message, 'error')
            }
            this.loader_transaction = false
        },
        async get_users(page = 1) {
            this.loader_spinner = true
            try {
                const query = {
                    p_page: page,
                    p_search: this.search,
                }
                const result = await this.$axios.post(this.$apiUrl + "getDownlineCustomer", query)
                this.list_users = result.data.data
                this.page_count = parseInt(result.data.pageCount)
            } catch (e) {
                this.$swal('Error', e.message, 'error')
            }
            this.loader_spinner = false
        },
    },
    async mounted() {
        await this.get_users()
    }
}
</script>

<style scoped lang="scss">
.pagination {
    display: flex;
    justify-content: center;
}

.gap-2 {
    margin-top: 0.5rem;
}

.gap-2>*:not(:last-child) {
    margin-right: 0.5rem;
}

.transaction-table {
    width: 100%;
}

.table-fixed {
    table-layout: fixed;
    width: 100%;
}

.table-header-wrapper {
    background: #fff;
    border-bottom: 1px solid #ddd;
}

.table-body-wrapper {
    height: 70vh;
    overflow-y: auto;
}

/* Prevent column mismatch */
.table-fixed th,
.table-fixed td {
    white-space: nowrap;
}

#transactionModal {
    z-index: 10000000 !important;
}

/* Allow the datepicker to overflow the modal container */
.vm--modal {
    overflow: visible !important;
}

/* Ensure the datepicker stays on top of the modal overlay */
.b-form-datepicker .dropdown-menu {
    z-index: 10000001 !important;
}

/* This targets the calendar popup when append-to-body is used */
.b-form-datepicker-calendar__outer,
.dropdown-menu.show {
    z-index: 10000001 !important;
}

.swal2-container {
    z-index: 10000002 !important;
}
</style>



