<template lang="html">
    <section class="tables">
        <div class="row">
            <div class="col-lg-12 grid-margin stretch-card">
                <div class="card">
                    <div class="card-body">
                        <h3 class="card-title mb-3">Website Banner</h3>

                        <div class="row mb-4" v-for="(banner, index) in banners" :key="index">
                            <!-- Title -->
                            <div class="col-12 text-center">
                                <h4 style="margin:0">Banner {{ index + 1 }}</h4>
                            </div>

                            <!-- Image -->
                            <div class="col-12 text-center banner-card-body">
                                <img :key="banner.url" :src="banner.url" :alt="'BANNER' + (index + 1)"
                                    class="banner-image">
                            </div>

                            <!-- Progress -->
                            <div class="col-12 text-center" v-if="progressInfos[index]">
                                <span>{{ progressInfos[index].fileName }}</span>
                                <div class="progress">
                                    <div class="progress-bar progress-bar-info" role="progressbar"
                                        :style="{ width: progressInfos[index].percentage + '%' }">
                                        {{ progressInfos[index].percentage }}%
                                    </div>
                                </div>
                            </div>

                            <!-- File Input -->
                            <div class="col-12 text-center">
                                <div class="form-group">
                                    <label><strong>Upload Image File:</strong></label>
                                    <input type="file" accept="image/*" class="form-control"
                                        @change="selectFile($event, index)">
                                </div>
                            </div>

                            <!-- Message -->
                            <div class="col-12 text-center" v-if="message">
                                <div class="alert alert-light">
                                    <ul>
                                        <li v-for="(ms, i) in message.split('\n')" :key="i">
                                            {{ ms }}
                                        </li>
                                    </ul>
                                </div>
                            </div>

                            <!-- Button -->
                            <div class="col-12 text-center">
                                <button class="btn btn-lg btn-primary" :disabled="!selectedFiles[index]"
                                    @click="uploadFile(index)">
                                    Change Banner
                                </button>
                            </div>
                        </div>

                    </div>
                </div>
            </div>
        </div>
    </section>
</template>
<script lang="js">
/* eslint-disable */
export default {
    name: 'website_banner',
    data() {
        return {
            banners: [],
            selectedFiles: {},
            progressInfos: {},
            message: ""
        }
    },
    methods: {
        async get_banner_url() {
            try {
                const res = await this.$axios.get(this.$apiUrl + "fetchBannerUrl");

                const ts = Date.now();

                this.banners = res.data.map(url => ({
                    url: `${url}?v=${ts}`
                }));
            } catch (e) {
                this.$swal("Error", e.message, "error");
            }
        },

        selectFile(event, index) {
            this.$set(this.selectedFiles, index, event.target.files[0]);
            this.$set(this.progressInfos, index, {
                percentage: 0,
                fileName: event.target.files[0].name
            });
        },

        async uploadFile(index) {
            const file = this.selectedFiles[index];

            try {
                await this.uploadToHttp(file, index + 1, progressEvent => {
                    this.progressInfos[index].percentage = Math.round(
                        (100 * progressEvent.loaded) / progressEvent.total
                    );
                });

                this.message = `Banner ${index + 1} updated successfully`;
                await this.get_banner_url();

                this.$delete(this.selectedFiles, index);
            } catch (e) {
                this.progressInfos[index].percentage = 0;
            }
        },

        uploadToHttp(file, bannerIndex, onUploadProgress) {
            const formData = new FormData();
            formData.append("media", file);
            formData.append("bannerIndex", bannerIndex);

            return this.$axios.post(this.$apiUrl + "uploadImage", formData, {
                headers: { "Content-Type": "multipart/form-data" },
                onUploadProgress
            });
        }
    },
    async mounted() {
        await this.get_banner_url()
    }
}

</script>

<style scoped>
.banner-card-body {
    display: flex;
    justify-content: center;
    /* horizontal center */
    align-items: center;
    /* vertical center */
    padding: 1rem;
    overflow: hidden;
}

.banner-image {
    max-width: 100%;
    height: auto;
    /* auto resize */
    object-fit: contain;
    /* no cropping */
    display: block;
}
</style>


